document.addEventListener("astro:page-load",()=>{const e=document.getElementById("copy-link-btn");e&&e.addEventListener("click",()=>{navigator.clipboard.writeText(window.location.href);const t=e.querySelector("span");if(t){const n=t.textContent;t.textContent=" Copied!",setTimeout(()=>{t.textContent=n},2e3)}});const o=document.getElementById("reading-progress");if(o){const t=()=>{const n=window.scrollY,s=document.documentElement.scrollHeight-window.innerHeight;if(s>0){const i=Math.min(n/s*100,100);o.style.width=i+"%"}};window.addEventListener("scroll",t,{passive:!0}),t()}});
